/// <summary>
/// COC of purchTotal form
/// </summary>
[ExtensionOf(formStr(PurchTotals))]
final class METPurchTotals_Extension
{
}

Method.Source:
    /// <summary>
    /// COC run method
    /// </summary>
    public void run()
    {
        next run();        

        if (callingTable.TableId == tableNum(PurchTable))
        {
            METMinOrderValue.visible(NoYes::Yes);
        }
        else
        {
            METMinOrderValue.visible(NoYes::Yes);
        }
        
    }

    /// <summary>
    /// COC setDisplayFields method
    /// </summary>
    void  setDisplayFields()
    {
        next setDisplayFields();
        if (callingTable.TableId == tableNum(PurchTable))
        {
            PurchTable      purchtable = callingTable as purchtable;
            METMinOrderVal  MinOrderValue = (select firstonly POMinimumOrderValue 
                                                from METPurchTable 
                                                where METPurchTable.purchId == purchtable.purchid).POMinimumOrderValue;
          
            METMinOrderValue.realValue(MinOrderValue);
        }

    }
